/* From Uiverse.io by catraco - Tags: checkbox, animated, click animation, cool checkbox, checkmark */
/* Hide the default checkbox */
.__UIV_SCOPE__ .container input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
}

.__UIV_SCOPE__ .container {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  cursor: pointer;
  font-size: 20px;
  user-select: none;
  border-radius: 50%;
  background-color: white;
}

/* Create a custom checkbox */
.__UIV_SCOPE__ .checkmark {
  position: relative;
  top: 0;
  left: 0;
  height: 1.3em;
  width: 1.3em;
  transition: .3s;
  transform: scale(0);
  border-radius: 50%;
}

/* When the checkbox is checked, add a blue background */
.__UIV_SCOPE__ .container input:checked ~ .checkmark {
  background-color: #20c580;
  transform: scale(1);
}

/* Create the checkmark/indicator (hidden when not checked) */
.__UIV_SCOPE__ .checkmark:after {
  content: "";
  position: absolute;
  display: none;
}

/* Show the checkmark when checked */
.__UIV_SCOPE__ .container input:checked ~ .checkmark:after {
  display: block;
}

.__UIV_SCOPE__ .container input:checked ~ .celebrate {
  display: block;
}

/* Style the checkmark/indicator */
.__UIV_SCOPE__ .container .checkmark:after {
  left: 0.45em;
  top: 0.25em;
  width: 0.30em;
  height: 0.5em;
  border: solid white;
  border-width: 0 0.15em 0.15em 0;
  transform: rotate(45deg);
}

.__UIV_SCOPE__ .container .celebrate {
  position: absolute;
  transform-origin: center;
  animation: kfr-celebrate .4s;
  animation-fill-mode: forwards;
  display: none;
  stroke: #20c580;
}

@keyframes kfr-celebrate {
  0% {
    transform: scale(0);
  }

  50% {
    opacity: 1;
  }

  100% {
    transform: scale(1.2);
    opacity: 0;
    display: none;
  }
}
